// eng_links.js — English link stemming, port of src/eng_links.py. A search
// word is expanded to every BLB word sharing a link head with it, so 'love'
// also matches loved, loves, loving, beloved... data/eng_links.tsv
// (word<TAB>head1,head2) is generated by tools/eng_links/build_links.py.
(function (global) {
  'use strict';

  let heads = null;   // word -> [heads]
  let forms = null;   // head -> Set(words)
  let loadPromise = null;

  function load() {
    if (loadPromise) return loadPromise;
    loadPromise = fetch('data/eng_links.tsv')
      .then((res) => {
        if (!res.ok) throw new Error(`Failed to fetch eng_links.tsv: HTTP ${res.status}`);
        return res.text();
      })
      .then((text) => {
        heads = new Map();
        forms = new Map();
        for (const line of text.split(/\r?\n/)) {
          if (!line) continue;
          const tab = line.indexOf('\t');
          const word = tab < 0 ? line : line.slice(0, tab);
          const hs = tab < 0 || tab === line.length - 1 ? [word] : line.slice(tab + 1).split(',');
          heads.set(word, hs);
          for (const h of hs) {
            if (!forms.has(h)) forms.set(h, new Set());
            forms.get(h).add(word);
          }
        }
      });
    return loadPromise;
  }

  // All forms linked to `word` (lowercased, includes the word itself).
  // Wildcard terms are returned unchanged -- stemming doesn't apply to them.
  function expand(word) {
    const w = word.toLowerCase();
    if (w.includes('*') || w.includes('?') || !heads) return [word];
    const out = new Set([w]);
    for (const h of heads.get(w) || []) {
      for (const f of forms.get(h) || []) out.add(f);
    }
    return Array.from(out).sort();
  }

  global.EngLinks = { load, expand };
})(window);
